import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import { Spinner } from "reactstrap";
import React, { Component } from "react";
import { Modal, ModalHeader, ModalBody } from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import { login, loadUser } from "../../../actions/authActions";
import { clearErrors } from "../../../actions/errorActions";
import store from "../../../store";
import { Button } from "@material-ui/core";

class UserAccessModal extends Component {
  state = {
    modal: false,
    chooseUserRowData: [],
    selectedUserRowData: [],
    tableLoaded: false,
    columns: [
      { title: "ID", field: "id", editable: "never" },
      { title: "Name", field: "name" }
    ]
  };
  componentDidMount() {
    this.retrieveFromDb();
  }
  toggle = () => {
    this.setState({
      modal: !this.state.modal
    });
  };
  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      chooseUserRowData: state.chooseUserRowData
    }));
    axios
      .get("/api/userList")
      .then(res => {
        var chooseUserRowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name
          };
        });

        this.setState(state => ({
          tableLoaded: true,
          chooseUserRowData
        }));
      })
      .catch(err => console.log(err));
  };

  addUser = event => {
    var chooseUserRowData = this.state.chooseUserRowData;
    /*var selectedUserRowData = this.state.selectedUserRowData;
    var removedUser = chooseUserRowData.splice(event.tableData.id, 1);*/
    chooseUserRowData.splice(event.tableData.id, 1);
    const addObject = {
      id: chooseUserRowData[event.tableData.id].id,
      name: chooseUserRowData[event.tableData.id].name
    };

    console.log(addObject);

    //selectedUserRowData.push(removedUser);
    this.setState({
      //selectedUserRowData,
      chooseUserRowData
    });
  };

  render() {
    return (
      <div>
        <Button
          className="mt-2 mb-3"
          variant="contained"
          color="primary"
          onClick={this.toggle}
        >
          Assign Users
        </Button>
        <Modal size={"lg"} isOpen={this.state.modal} toggle={this.toggle}>
          <ModalHeader toggle={this.toggle}>Assign Users</ModalHeader>
          <ModalBody>
            {this.state.tableLoaded ? (
              <div>
                <MaterialTable
                  columns={this.state.columns}
                  data={this.state.chooseUserRowData}
                  title={<h5>Choose Users</h5>}
                  options={{
                    search: false,
                    showTitle: true,
                    toolbar: true
                  }}
                  onRowClick={(rowdata, event) => {
                    this.addUser(event);
                  }}
                  //////
                />
                <div className="mb-3"> </div>
                <MaterialTable
                  columns={this.state.columns}
                  data={this.state.selectedUserRowData}
                  title={<h5>Selected Users</h5>}
                  options={{
                    search: false,
                    showTitle: true,
                    toolbar: true
                  }}
                  onRowClick={(rowdata, event) => {
                    console.log("remove record");
                  }}
                  //////
                />

                <div
                  style={{
                    display: "flex",
                    flexDirection: "row-reverse"
                  }}
                >
                  <Button
                    className="mt-3 "
                    variant="contained"
                    color="primary"
                    onClick={this.toggle}
                  >
                    Assign Users
                  </Button>
                </div>
              </div>
            ) : (
              <div
                style={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Spinner animation="border" />
              </div>
            )}
          </ModalBody>
        </Modal>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isAutheticated: state.auth.isAutheticated,
  error: state.error
});

export default connect(mapStateToProps, null)(UserAccessModal);
//mapStateToProps gets state variables from elsewhere in the app.
//the stuff in the curly braces are methods brought in to modify state in other parts of the app
//all these things will be declared in the component props
